def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = g[0][0]

    sep_row = next((r for r in range(h) if len(set(g[r])) == 1 and g[r][0] != bg), None)
    if sep_row is not None:
        src = next(r for r in range(sep_row) if any(x != bg for x in g[r]))
        dst = sep_row - 1
        ref = next(r for r in range(sep_row + 1, h) if any(x != bg for x in g[r]))
        for c in range(w):
            if g[src][c] != g[ref][c]:
                g[0][c] = g[src][c]
            else:
                g[dst][c] = g[src][c]
            g[src][c] = bg
        return g

    sep_col = next(c for c in range(w) if len({g[r][c] for r in range(h)}) == 1 and g[0][c] != bg)
    src = next(c for c in range(sep_col) if any(g[r][c] != bg for r in range(h)))
    dst = sep_col - 1
    ref = next(c for c in range(sep_col + 1, w) if any(g[r][c] != bg for r in range(h)))
    for r in range(h):
        if g[r][src] != g[r][ref]:
            g[r][0] = g[r][src]
        else:
            g[r][dst] = g[r][src]
        g[r][src] = bg
    return g
